let productoBuscado = null;

try {
    const salida = $('AI Agent2').first().json.output;
    const parsed =
        typeof salida === 'string'
            ? JSON.parse(salida)
            : salida;

    productoBuscado = parsed.producto ?? null;
} catch (e) {
    productoBuscado = null;
}


