    const d = items[0] || {};

    return [{
        json: {
            modo: "especifico",
            pregunta_usuario: $('Webhook').first().json.body.pregunta,
            producto: d.producto ?? productoBuscado,
            fecha_ultimo_registro: d.fecha_ultimo_registro ?? null,
            precio_actual: d.precio_actual ?? null,
            precio_promedio_7: d.precio_promedio_7 ?? null,
            precio_promedio_30: d.precio_promedio_30 ?? null,
            volumen_actual_t: d.volumen_actual_t ?? null,
            comparacion_7_dias: d.comparacion_7_dias ?? null
        }
    }];
}


// CONSULTA GENERAL DEL MERCADO
return [{
    json: {
        modo: "general",
        pregunta_usuario: $('Webhook').first().json.body.pregunta,
        mercado: "Gran Mercado Mayorista de Lima",
        productos_analizados: items.length,
