// 1. Traemos el clima y los precios usando la sintaxis moderna
const satelite = $('HTTP Request open meteo1').first().json; 
const precios = $input.all();

// 2. Traemos de forma segura lo que entendió la primera IA
const texto_primera_ia = $('Switch1').first().json.output;
const datos_usuario = JSON.parse(texto_primera_ia);

// 3. Armamos el reporte completo incluyendo el producto y la ciudad
const reporte = `
CONTEXTO DE LA CONSULTA:
- Producto a evaluar: ${datos_usuario.producto}
- Ubicación: ${datos_usuario.lugar}

DATOS DEL CLIMA (Open-Meteo):
${JSON.stringify(satelite.daily)}

HISTORIAL DE PRECIOS (Últimos 7 días):
${JSON.stringify(precios)}
`;

return { prompt_final: reporte };

const respuesta = $input.first().json;

const vector = respuesta.data?.[0]?.embedding;

if (!Array.isArray(vector) || vector.length === 0) {
  throw new Error(
    'No se pudo obtener el embedding de Jina AI'
  );
}

if (vector.length !== 384) {
  throw new Error(
    `Dimensión inesperada: ${vector.length}. Se esperaban 384 dimensiones.`
  );
}

return [{
  json: {
    dimension: vector.length,
    embedding: `[${vector.join(',')}]`
  }
}];

const documentos = $input.all();

const meses = {
  enero: '01',
  febrero: '02',
  marzo: '03',
  abril: '04',
  mayo: '05',
  junio: '06',
  julio: '07',
  agosto: '08',
  septiembre: '09',
  setiembre: '09',
  octubre: '10',
  noviembre: '11',
  diciembre: '12'
};

function extraerFecha(texto) {
  if (!texto) return null;

  const match = texto.match(
    /(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)\s+de\s+(\d{4})/i
  );

  if (!match) return null;

  const dia = match[1].padStart(2, '0');
  const mes = meses[match[2].toLowerCase()];
  const anio = match[3];

  return `${anio}-${mes}-${dia}`;
}

const contexto = documentos
  .map((item, index) => {

    const metadata = item.json.metadata || {};
    const texto = item.json.text || '';

    const fecha =
      metadata.fecha ||
      metadata.date ||
      extraerFecha(texto) ||
      'Fecha no especificada';

    const fuente =
      metadata.filename ||
      metadata.archivo ||
      metadata.fuente ||
      'Boletín Diario MIDAGRI - GMML';

    return `
DOCUMENTO ${index + 1}

FUENTE: ${fuente}
FECHA: ${fecha}
DISTANCIA COSENO: ${item.json.distancia_coseno}

CONTENIDO:
${texto}
`;
  })
  .join('\n-----------------------------\n');

return [{
  json: {
    pregunta_usuario: $('Webhook').first().json.body.pregunta,
    contexto,
    documentos_recuperados: documentos.length
  }
}];

const d = $json;

if (!d.producto || d.volumen_t == null) {
  return [{
    json: {
      respuesta: "No encontré un volumen de ingreso registrado para ese producto."
    }
  }];
}

const toneladas = Number(d.volumen_t);
const kilos = Number(d.volumen_kg);
const equivalencia = Number(d.equivalencia_kg);


return [{
  json: {
    pregunta_usuario: $('Webhook').first().json.body.pregunta,
    producto: d.producto,
    fecha: d.fecha,
    volumen_t: d.volumen_t,
    volumen_kg: d.volumen_kg,
    unidad: d.unidad,
    equivalencia_kg: d.equivalencia_kg
  }
}];

const items = $input.all().map(item => item.json);

if (!items.length || !items[0].producto) {
  return [{
    json: {
      respuesta: "No se encontró un precio registrado para la consulta solicitada."
    }
  }];
}

// Solo un producto/variedad encontrada
if (items.length === 1) {
  const d = items[0];

  if (d.precio == null || !d.fecha) {
    return [{
      json: {
        respuesta: "No se encontró un precio registrado para la fecha solicitada."
      }
    }];
  }

  const fecha = new Date(d.fecha);

  const fechaNatural = fecha.toLocaleDateString('es-PE', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC'
  });

  const unidad = (d.unidad || 'unidad').toLowerCase();

  return [{
    json: {
      respuesta:
        `El precio más reciente registrado de ${d.producto} es de S/ ${d.precio} por ${unidad}, correspondiente al ${fechaNatural}.`
    }
  }];
}


// Varias variedades encontradas
const lineas = items.map(d => {
  const fecha = d.fecha
    ? new Date(d.fecha).toLocaleDateString('es-PE', {
        day: 'numeric',
        month: 'long',
        year: 'numeric',
        timeZone: 'UTC'
      })
    : 'fecha no disponible';

  const unidad = (d.unidad || 'unidad').toLowerCase();

  return `- ${d.producto}: S/ ${d.precio} por ${unidad} (${fecha})`;
});

return [{
  json: {
    respuesta:
      `Encontré varias variedades disponibles:\n\n${lineas.join('\n')}\n\nSi deseas consultar una variedad específica, indícame su nombre.`
  }
}];

// ==========================================
// PREPARAR ERROR PARA LANGFUSE
// ==========================================

function hexAleatorio(bytes) {
  let resultado = '';

  for (let i = 0; i < bytes; i++) {
    resultado += Math
      .floor(Math.random() * 256)
      .toString(16)
      .padStart(2, '0');
  }

  return resultado;
}


// ==========================================
// TRACE ID DE LA CONSULTA
// ==========================================

let traceId = null;

try {
  traceId =
    $('Code - Inicio Trace')
      .first()
      .json
      .langfuse_trace_id;
} catch (error) {
  traceId = null;
}


// ==========================================
// PREGUNTA DEL USUARIO
// ==========================================

let pregunta = null;

try {
  pregunta =
    $('Webhook')
      .first()
      .json
      .body
      .pregunta ?? null;
} catch (error) {
  pregunta = null;
}


// ==========================================
// TIPO DE CONSULTA
// ==========================================

let tipoConsulta = 'desconocido';

try {
  const salidaAgent =
    $('AI Agent2')
      .first()
      .json
      .output;

  const clasificacion =
    typeof salidaAgent === 'string'
      ? JSON.parse(salidaAgent)
      : salidaAgent;

  tipoConsulta =
    clasificacion?.tipo_consulta ??
    'desconocido';

} catch (error) {
  tipoConsulta = 'desconocido';
}


// ==========================================
// EXTRAER ERROR RECIBIDO
// ==========================================

const errorEntrada =
  $json.error ??
  $json.message ??
  $json.description ??
  $json;


// ==========================================
// CONVERTIR ERROR A TEXTO SEGURO
// ==========================================

let errorTexto = '';

try {
  errorTexto =
    typeof errorEntrada === 'string'
      ? errorEntrada
      : JSON.stringify(errorEntrada);
} catch (error) {
  errorTexto = 'Error no serializable';
}


// ==========================================
// SANITIZAR DATOS SENSIBLES
// ==========================================

errorTexto = errorTexto
  .replace(/sk-[A-Za-z0-9_-]+/gi, '[REDACTED_API_KEY]')
  .replace(/Bearer\s+[A-Za-z0-9._-]+/gi, 'Bearer [REDACTED]')
  .replace(/postgres(?:ql)?:\/\/[^"\s]+/gi, '[REDACTED_DATABASE_URL]')
  .replace(/password["'=:\s]+[^,\s"}]+/gi, 'password=[REDACTED]')
  .slice(0, 1500);


// ==========================================
// CLASIFICAR ERROR
// ==========================================

let tipoError = 'ERROR_GENERAL';

const textoLower =
  errorTexto.toLowerCase();

if (
  textoLower.includes('429') ||
  textoLower.includes('rate limit')
) {
  tipoError = 'HTTP_429';
}

else if (
  textoLower.includes('timeout') ||
  textoLower.includes('timed out')
) {
  tipoError = 'TIMEOUT';
}

else if (
  textoLower.includes('postgres') ||
  textoLower.includes('database') ||
  textoLower.includes('connection refused') ||
  textoLower.includes('connection terminated')
) {
  tipoError = 'DATABASE_ERROR';
}

else if (
  textoLower.includes('openrouter') ||
  textoLower.includes('llm') ||
  textoLower.includes('model')
) {
  tipoError = 'LLM_ERROR';
}


// ==========================================
// MENSAJE CONTROLADO PARA EL USUARIO
// ==========================================

let mensajeUsuario =
  'No se pudo procesar la consulta en este momento. Intenta nuevamente más tarde.';

if (tipoError === 'HTTP_429') {
  mensajeUsuario =
    'El servicio de inteligencia artificial está temporalmente ocupado. Intenta nuevamente en unos segundos.';
}

else if (tipoError === 'TIMEOUT') {
  mensajeUsuario =
    'La consulta tardó más de lo esperado. Intenta nuevamente en unos segundos.';
}

else if (tipoError === 'DATABASE_ERROR') {
  mensajeUsuario =
    'No se pudo consultar la información almacenada en este momento. Intenta nuevamente más tarde.';
}


// ==========================================
// TIMESTAMP
// ==========================================

const ahoraMs = Date.now();


// ==========================================
// RETORNO
// ==========================================

return [{
  json: {

    trace_id:
      traceId ?? hexAleatorio(16),

    span_id:
      hexAleatorio(8),

    nombre_observacion:
      'AgroSmart - Error',

    tipo_consulta:
      tipoConsulta,

    tipo_error:
      tipoError,

    pregunta:
      pregunta,

    error_detalle:
      errorTexto,

    mensaje_usuario:
      mensajeUsuario,

    inicio_ns:
      (BigInt(ahoraMs - 1) * 1000000n).toString(),

    fin_ns:
      (BigInt(ahoraMs) * 1000000n).toString(),

    level:
      'ERROR'
  }
}];

